DECLARE @Columns NVARCHAR(MAX), @SQL NVARCHAR(MAX);

-- Build the column list from whatever months actually exist in range
SELECT @Columns = STRING_AGG(QUOTENAME(MonthLabel), ',')
FROM (
    SELECT DISTINCT FORMAT(OrderDate, 'yyyy-MM') AS MonthLabel
    FROM Sales.SalesOrderHeader
    WHERE OrderDate BETWEEN @StartDate AND @EndDate
) AS Months;

SET @SQL = N'
SELECT ProductName, ' + @Columns + N'
FROM (
    SELECT p.Name AS ProductName, FORMAT(soh.OrderDate, ''yyyy-MM'') AS MonthLabel, sod.LineTotal
    FROM Sales.SalesOrderDetail sod
    JOIN Sales.SalesOrderHeader soh ON soh.SalesOrderID = sod.SalesOrderID
    JOIN Production.Product p ON p.ProductID = sod.ProductID
    WHERE soh.OrderDate BETWEEN @StartDate AND @EndDate
) AS SourceData
PIVOT (SUM(LineTotal) FOR MonthLabel IN (' + @Columns + N')) AS PivotTable;';

EXEC sp_executesql @SQL,
    N'@StartDate DATE, @EndDate DATE',
    @StartDate = @StartDate, @EndDate = @EndDate;

-- Before: row-by-row cursor, each UPDATE its own mini-operation
DECLARE @CustomerID INT;
DECLARE loyalty_cursor CURSOR FOR
    SELECT CustomerID FROM dbo.DailyPurchases WHERE PurchaseDate = @Today;
OPEN loyalty_cursor;
FETCH NEXT FROM loyalty_cursor INTO @CustomerID;
WHILE @@FETCH_STATUS = 0
BEGIN
    UPDATE dbo.Customer SET LoyaltyPoints = LoyaltyPoints + 10 WHERE CustomerID = @CustomerID;
    FETCH NEXT FROM loyalty_cursor INTO @CustomerID;
END
CLOSE loyalty_cursor; DEALLOCATE loyalty_cursor;

-- After: one set-based statement, processed as a single batch
UPDATE c
SET c.LoyaltyPoints = c.LoyaltyPoints + 10
FROM dbo.Customer c
JOIN dbo.DailyPurchases dp ON dp.CustomerID = c.CustomerID
WHERE dp.PurchaseDate = @Today;

// Before: exception swallowed, row disappears silently
try {
    var parts = Row.RawField.Split('|');
    Row.ValueA = parts[0];
    Row.ValueB = parts[1];
    Row.ValueC = parts[2];
} catch (Exception) {
    // nothing -- row never reaches any output
}

// After: failure redirected to a visible, countable error output
try {
    var parts = Row.RawField.Split('|');
    Row.ValueA = parts[0];
    Row.ValueB = parts[1];
    Row.ValueC = parts[2];
} catch (Exception ex) {
    ErrorOutputBuffer.AddRow();
    ErrorOutputBuffer.RawField = Row.RawField;
    ErrorOutputBuffer.ErrorMessage = ex.Message;
}

